.evidence-intake :is(input, select, textarea):optional { border-inline-start: .25rem solid #9aaeb8; }
@media (forced-colors: active) { .evidence-intake :is(input, select, textarea):required { border-inline-start-color: CanvasText; } }

.case-lookup input { background: #fff; color: #173441; border: 1px solid #58707d; }
.case-lookup input::placeholder { color: #506572; opacity: 1; }
.case-lookup input:focus-visible { outline: 3px solid #1c5e87; outline-offset: 2px; }

.claim-queue > li { background: #fff; }
.claim-queue > li:nth-child(even of :not([hidden])) { background: #edf4f7; }
.claim-queue > li:focus-within { outline: 2px solid #1c5e87; outline-offset: 2px; }

.case-note { padding-inline: 1rem; border-inline-start: .25rem solid #396c82; }
.case-note:dir(rtl) .case-note__actions { text-align: start; border-inline-start: .15rem solid #819aa5; }
.case-note:dir(ltr) .case-note__actions { text-align: start; border-inline-start: .15rem solid #396c82; }

.archive-index { writing-mode: vertical-rl; text-orientation: mixed; max-block-size: 18rem; }
.archive-index__badge { text-orientation: upright; font-weight: 700; }
.archive-index a:focus-visible { outline: 3px solid #1c5e87; outline-offset: 3px; }

.catalog-copy:lang(ja) strong { text-emphasis: filled dot #803a42; text-emphasis-position: over right; }
.catalog-copy:lang(ja) { line-height: 1.8; }
@media print { .catalog-copy:lang(ja) strong { text-emphasis-color: currentColor; } }

@font-face { font-family: "Annotation Axis"; src: url("/assets/annotation-axis.woff2") format("woff2"); font-weight: 300 700; }
.annotation-label { font-family: "Annotation Axis", sans-serif; font-weight: 520; font-variation-settings: "GRAD" 40; }
.annotation-label--quiet { font-variation-settings: "GRAD" 0; }

.training-player:fullscreen { display: grid; place-items: center; padding: 1rem; background: #081b26; color: #fff; }
.training-player:fullscreen video { max-inline-size: 100%; max-block-size: 85vh; }
.training-player:fullscreen :focus-visible { outline: 3px solid #f4c65f; outline-offset: 3px; }

.review-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 19rem), 1fr)); gap: 1rem; }
.review-grid > article { min-inline-size: 0; }
.review-grid--reserved { grid-template-columns: repeat(auto-fill, minmax(min(100%, 19rem), 1fr)); }

.status-tile { overflow: clip; border-radius: .55rem; }
.status-tile__content { position: relative; z-index: 1; }
.transcript-pane { max-block-size: 21rem; overflow: auto; }

.audit-help > summary { border-block-end: 1px solid #78909c; padding: .6rem; }
.audit-help[open] > summary { background: #e9f2f6; }
.audit-help:open > summary { border-block-end-color: #1c5e87; }
.audit-help > summary:focus-visible { outline: 3px solid #1c5e87; outline-offset: 2px; }

.case-lookup input { border: 2px solid #5e7480; }
.case-lookup input:user-valid { border-color: #1f6b4b; }
.case-lookup input:user-invalid { border-color: #a33b42; }
.case-lookup input:focus-visible { outline: 3px solid #1c5e87; outline-offset: 2px; }

.comparison-panel { color: #173441; background: #f5f8f9; border: 1px solid #7b929d; }
@supports (backdrop-filter: blur(1px)) { .comparison-panel { background: rgb(245 248 249 / 94%); backdrop-filter: blur(6px); } }
@media (prefers-reduced-transparency: reduce) { .comparison-panel { background: #f5f8f9; backdrop-filter: none; } }

@keyframes review-nudge { 50% { transform: translateY(-.35rem); } }
.review-marker { transform: translateX(.65rem); }
@supports (animation-composition: add) { .review-marker { animation: review-nudge 520ms ease-out 1; animation-composition: add; } }
@media (prefers-reduced-motion: reduce) { .review-marker { animation: none; } }

.case-study__intro { max-inline-size: 62ch; text-wrap: wrap; text-wrap: pretty; }
.case-study__activity { text-wrap: wrap; }
.case-study__editable-note { text-wrap: stable; }

:host { display: block; color: #173441; border: 1px solid var(--shipment-accent, #315f75); padding: 1rem; }
:host([density="compact"]) { padding: .65rem; }
.status-row { display: flex; flex-wrap: wrap; gap: .75rem; }
:host([density="compact"]) .status-row { gap: .4rem; }

.review-card.is-transition-source { view-transition-name: selected-case; }
.case-detail.is-transition-target { view-transition-name: selected-case; }
@media (prefers-reduced-motion: reduce) { ::view-transition-old(selected-case), ::view-transition-new(selected-case) { animation-duration: .01ms; } }

::view-transition-old(selected-case) { animation: case-exit 180ms ease-in both; }
::view-transition-new(selected-case) { animation: case-enter 180ms ease-out both; }
@keyframes case-exit { to { opacity: 0; } }
@keyframes case-enter { from { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { ::view-transition-old(selected-case), ::view-transition-new(selected-case) { animation: none; } }

.dispatch-card { border: 1px solid #597581; padding: 1rem; }
@supports selector(:has(input:checked)) { .dispatch-card:has(> .hold-control input:checked) { border-inline-start: .35rem solid #7a382e; } }
.dispatch-card:focus-within { outline: 2px solid #205d78; outline-offset: 2px; }

.incident-heading { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: .55rem; row-gap: .25rem; }
.incident-heading__count { font: 700 2.2rem/1 system-ui; }
.incident-heading__label { font: 600 1rem/1.4 system-ui; max-inline-size: 24ch; }

audit-summary { display: block; min-block-size: 4rem; padding: .8rem; border: 1px solid #6e8792; color: #173441; }
 audit-summary:not(:defined) { border-style: dashed; background: #f4f7f8; }
 audit-summary:defined { border-color: #315f75; }

.policy-note { border: 1px solid #708891; border-radius: .35rem; padding: .75rem; color: #173441; }
.policy-note > summary { font-weight: 700; cursor: pointer; }
.policy-note::details-content { margin-block-start: .65rem; padding-block-start: .65rem; border-block-start: 1px solid #a8b7bd; }

@view-transition { navigation: auto; }
::view-transition-old(root), ::view-transition-new(root) { animation-duration: 140ms; }
@media (prefers-reduced-motion: reduce) { ::view-transition-old(root), ::view-transition-new(root) { animation: none; } }

.dispatch-list { display: block; }
.script-unavailable-note { display: none; }
@media (scripting: none) { .script-unavailable-note { display: block; color: #173441; background: #eef4f6; padding: .75rem; } }

.reject-dialog { box-sizing: border-box; max-inline-size: min(34rem, calc(100vw - 2rem)); max-block-size: calc(100dvh - 2rem); overflow: auto; color: #173441; background: #f7fafb; }
.reject-dialog:modal { border: 3px solid #325f73; }
.reject-dialog :focus-visible { outline: 3px solid #1b657f; outline-offset: 2px; }
